/**
 * Robustly remove generated native dirs (android/ and/or ios/) before an
 * `expo prebuild --clean`.
 *
 * Expo's own clean step sometimes fails with
 *   "ENOTEMPTY: directory not empty, rmdir '.../android/app'"
 * when a leftover build artifact (or a file re-created mid-delete by a lingering
 * Gradle daemon / editor) blocks its non-recursive rmdir. Node's fs.rmSync with
 * { recursive: true, force: true, maxRetries } deletes children first and
 * retries on transient EBUSY/ENOTEMPTY, so prebuild then starts from a clean
 * slate. The dirs are fully regenerated by prebuild, so removing them is safe.
 *
 * Usage: node scripts/clean-native-dirs.js [android] [ios]   (defaults to both)
 */
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const args = process.argv.slice(2).filter(Boolean);
const targets = args.length ? args : ["android", "ios"];

for (const t of targets) {
  const dir = path.join(root, t);
  if (!fs.existsSync(dir)) {
    continue;
  }
  try {
    fs.rmSync(dir, { recursive: true, force: true, maxRetries: 8, retryDelay: 250 });
    console.log(`clean-native-dirs: removed ${t}/`);
  } catch (err) {
    console.error(
      `clean-native-dirs: could not remove ${t}/ (${err.message}). ` +
        "Close Android Studio/Xcode and stop the Gradle daemon " +
        "(cd apps/mobile/android && ./gradlew --stop), then retry.",
    );
    process.exitCode = 1;
  }
}
